#!/usr/bin/env python3
"""Teste representativo de locução de jornal (assuntos reais gerais; SEM notícias atuais verificadas).
Nunca emitir, não envia a RadioDJ/R2. Quantifica bytes, chamadas e duração.
"""
import json, os, subprocess, urllib.request, time
from pathlib import Path

SECTIONS=[["ABERTURA","Boa tarde. Está a ouvir a VelvetVerse Radio, a partir de Toronto. Esta é uma edição experimental do VelvetVerse Notícias, produzida exclusivamente para avaliar a duração e os custos da locução automática. Não se trata de um noticiário em direto, nem de uma edição destinada à emissão. Vamos acompanhar, com linguagem clara e rigorosa, os grandes temas internacionais, assuntos portugueses, o desporto canadiano e o futebol de Portugal. No final, reservamos um espaço para explicar como se apresenta a previsão meteorológica em rádio. A nossa intenção é verificar a naturalidade da voz, o ritmo, a dicção e as pausas entre assuntos, simulando a experiência de um verdadeiro boletim dominical."],["INTERNACIONAL — ENERGIA E CLIMA","A transição energética continua a ser um dos grandes desafios internacionais. Para governos, empresas e famílias, o debate envolve segurança do abastecimento, custos de produção, investimentos e proteção do ambiente. Quando uma fonte noticiosa anuncia novos compromissos, é importante distinguir entre um objetivo político, um acordo assinado e uma medida já aplicada. As datas também contam: um plano para a próxima década não significa uma mudança imediata nas contas dos consumidores. No jornalismo radiofónico, a missão é explicar os factos sem confundir intenções com resultados. Por isso, ao preparar uma reportagem sobre energia, a redação deve comparar os documentos oficiais, ouvir posições diferentes e identificar com precisão aquilo que está confirmado. Também importa apresentar o impacto das medidas na vida quotidiana, desde a mobilidade até aos preços da eletricidade. Uma notícia completa não se limita ao título. Precisa de contexto, de uma sequência lógica e de informação suficiente para que o ouvinte compreenda as consequências possíveis, sem transformar previsões em certezas."],["INTERNACIONAL — ECONOMIA MUNDIAL","O comportamento da economia mundial influencia os preços, o emprego e as decisões de investimento em países muito diferentes. Taxas de juro, inflação, comércio internacional e disponibilidade de matérias-primas estão frequentemente relacionados, mas não evoluem sempre no mesmo sentido. Uma descida de preços num setor não representa, necessariamente, uma redução do custo de vida em geral. Para apresentar uma notícia económica com rigor, é necessário indicar o país, o período de referência, a fonte estatística e a comparação utilizada. Se um indicador subir, o ouvinte deve saber em relação a quê: ao mês anterior, ao mesmo mês do ano passado ou a uma previsão inicial. Essa distinção, aparentemente simples, pode alterar completamente a interpretação. Num noticiário de rádio, os números devem ser apresentados com clareza, sem uma sucessão excessiva de percentagens. O essencial é dar ao público a informação suficiente para perceber o que mudou, o que permanece incerto e quais são os próximos passos conhecidos."],["PORTUGAL — HABITAÇÃO","Em Portugal, a habitação é um tema com impacto direto na vida de milhares de famílias. A disponibilidade de casas, o valor das rendas e as condições de acesso ao crédito exigem explicações cuidadas. Sempre que surge uma proposta do Governo ou uma nova medida parlamentar, é necessário esclarecer se estamos perante um anúncio, uma votação, uma lei publicada ou uma medida que já entrou em vigor. Estas etapas não são equivalentes. Também convém distinguir a situação das grandes cidades da realidade de outras regiões, porque os preços e a oferta variam. Um tratamento radiofónico equilibrado deve procurar os dados oficiais mais recentes e explicar o alcance das decisões, sem prometer efeitos que ainda não podem ser demonstrados. O objetivo é que o ouvinte termine a notícia a saber o que aconteceu, quem foi afetado e onde poderá encontrar esclarecimentos adicionais. A clareza é particularmente importante quando os assuntos envolvem contratos, apoios públicos ou prazos legais."],["PORTUGAL — TRABALHO E SALÁRIOS","O trabalho e os salários são outra área central da informação nacional. Sempre que há negociações sobre remunerações, contratos ou direitos dos trabalhadores, a redação precisa de confirmar os valores e as datas nas fontes competentes. A proposta de um aumento salarial, por exemplo, não deve ser apresentada como uma decisão em vigor antes de concluído o processo correspondente. Para quem vive fora de Portugal, incluindo muitos ouvintes da VelvetVerse Radio no Canadá, esta contextualização é ainda mais importante. Nem todos acompanham diariamente os debates políticos e sociais portugueses. Uma boa notícia deve ser compreensível sem depender de conhecimentos prévios. Deve explicar os termos essenciais, evitar linguagem excessivamente técnica e diferenciar as posições dos intervenientes. Quando existem números, importa apresentá-los de forma simples e verificar se são valores brutos, líquidos, mensais ou anuais. É esta atenção ao detalhe que transforma um texto informativo numa peça útil para o público."],["PORTUGAL — TRANSPORTES E SERVIÇOS","Os transportes e os serviços públicos são temas recorrentes na atualidade portuguesa. Alterações de horários, obras, greves, investimentos e mudanças no atendimento podem influenciar diretamente a rotina dos cidadãos. A informação de serviço deve ser particularmente cuidadosa: um aviso incompleto pode levar alguém a deslocar-se inutilmente ou a planear mal uma viagem. Antes de divulgar uma mudança, o jornal deve confirmar o local, a data, o período de aplicação e, sempre que exista, uma alternativa. Também deve evitar tratar um projeto anunciado como uma obra concluída. O público ganha quando o jornalista apresenta os factos em frases curtas, com indicações práticas e sem dramatização desnecessária. Quando o assunto tem desenvolvimentos constantes, é preferível referir a hora da atualização e lembrar que poderão existir alterações posteriores. A rádio mantém assim uma relação de confiança com quem a acompanha, tanto em casa como em viagem."],["TRANSIÇÃO PARA O DESPORTO","Mudamos agora de assunto. Depois dos destaques internacionais e de Portugal, entramos na informação desportiva. Começamos pelo Canadá e seguimos para o futebol português."],["DESPORTO CANADÁ — HÓQUEI","No Canadá, o hóquei no gelo ocupa um lugar especial na cultura desportiva. As competições profissionais, as seleções nacionais e o desenvolvimento do desporto feminino mobilizam adeptos de diferentes gerações. Num jornal de domingo, o destaque deve recair sobre um resultado recente ou sobre um acontecimento realmente importante, e não apenas sobre a primeira manchete encontrada num sítio de notícias. Para transmitir um resultado com rigor, é indispensável confirmar a competição, as equipas, o marcador final e a data do encontro. Também é necessário evitar confundir resultados provisórios com jogos terminados. Se ainda estiver em curso uma partida, o noticiário deve dizê-lo claramente, identificando a hora da informação. A mesma regra aplica-se a lesões, transferências e decisões disciplinares: uma possibilidade não é uma confirmação. Esta edição experimental serve precisamente para testar a leitura de nomes próprios, a alternância entre assuntos e a pronúncia portuguesa de referências canadianas, sem apresentar resultados desportivos inventados."],["FUTEBOL PORTUGUÊS — CAMPEONATO","E vamos agora ao futebol português, que terá três destaques na edição habitual do VelvetVerse Notícias. O campeonato nacional é acompanhado de perto por adeptos do Benfica, Sporting, Futebol Clube do Porto e de muitos outros clubes. A cada jornada, os resultados podem modificar a classificação, mas essa alteração deve ser confirmada depois de os jogos terminarem. Para o ouvinte, é útil saber não só quem venceu, mas também o contexto do encontro e o que está em disputa. Num boletim dominical, a redação deve dar prioridade aos jogos de sexta-feira e sábado, verificando resultados e incidências nas fontes oficiais. Os encontros marcados para mais tarde devem aparecer como agenda, nunca como resultados antecipados. Também queremos evitar repetir a mesma notícia com títulos diferentes. O futebol merece destaque, mas merece igualmente equilíbrio, rigor e respeito por todos os clubes."],["FUTEBOL PORTUGUÊS — SELEÇÃO","A seleção nacional portuguesa é outro assunto de grande interesse para quem acompanha futebol dentro e fora do país. Convocatórias, encontros internacionais, competições e decisões técnicas geram atenção, mas exigem a mesma disciplina jornalística aplicada aos restantes temas. Uma convocatória só deve ser apresentada como oficial depois de comunicada pela entidade competente. No caso de uma alteração de última hora, importa confirmar a atualização e esclarecer o motivo quando houver informação pública suficiente. Também é fundamental distinguir declarações de jogadores ou treinadores de decisões já tomadas. As notícias sobre o futuro de um atleta, por exemplo, não devem transformar uma opinião ou especulação numa realidade confirmada. Para a VelvetVerse Radio, o objetivo é transmitir os acontecimentos em português de Portugal, com um ritmo adequado à rádio, sem exageros e sem tomar partido por uma equipa ou personalidade."],["FUTEBOL PORTUGUÊS — COMPETIÇÕES INTERNACIONAIS","O terceiro destaque do futebol português poderá abordar a participação dos clubes nas competições europeias ou os preparativos para os grandes torneios internacionais. Nestes assuntos, o contexto é tão importante como o resultado. Um jogo pode influenciar o apuramento, a classificação ou o calendário, mas as consequências precisam de ser calculadas a partir dos regulamentos e dos resultados confirmados. Se uma equipa ainda depender de encontros de adversários, é necessário explicar essa condição. No caso de obras em estádios ou de decisões sobre a organização de competições, o jornalista deve diferenciar avaliações, anúncios e confirmações oficiais. A boa informação desportiva não procura apenas a emoção do momento. Procura também explicar de maneira acessível aquilo que os acontecimentos representam para jogadores, clubes e adeptos. E é com esse compromisso que queremos construir a secção de futebol do nosso futuro jornal semanal."],["TRANSIÇÃO PARA A METEOROLOGIA","Concluída a informação desportiva, passamos à meteorologia. Primeiro, o Canadá. Depois, Portugal. Em cada edição verdadeira, a previsão será atualizada para o próprio domingo e para a segunda-feira seguinte."],["METEOROLOGIA CANADÁ","Começamos por Toronto. Num boletim real, apresentaremos a temperatura mínima e máxima prevista, o estado geral do céu e a possibilidade de precipitação para domingo e segunda-feira. Os valores deverão ser obtidos pouco antes da emissão e identificados com a respetiva data, porque as previsões mudam. A forma de dizer a informação também é importante. Em vez de ler uma sequência de números isolados, o locutor deve organizar a mensagem em frases naturais, começando pelo dia e continuando com as condições esperadas. Quando houver avisos meteorológicos oficiais, a redação deverá confirmar a respetiva validade antes de os divulgar. Este é um exemplo de leitura e não uma previsão atual. Por isso, não são apresentados aqui valores inventados de temperatura, neve ou chuva."],["METEOROLOGIA PORTUGAL","Olhando agora para Portugal, o boletim habitual acompanhará Lisboa, Porto e Faro. Para cada cidade, indicaremos a previsão para domingo e para segunda-feira, numa linguagem clara e compreensível. O estado do tempo poderá ser diferente entre o Norte, a região de Lisboa e o Algarve, pelo que não devemos generalizar a partir de uma única cidade. Também será importante distinguir uma probabilidade de precipitação de uma previsão de chuva contínua. Sempre que existirem avisos relevantes, a informação deve ser consultada junto das autoridades meteorológicas competentes e apresentada com as datas corretas. No fim, recordaremos que as condições podem sofrer alterações. Nesta edição de ensaio, o nosso propósito é avaliar como a voz lê nomes de localidades, temperaturas, datas e expressões meteorológicas, e não substituir as previsões oficiais."],["FECHO","Chegamos ao final desta edição experimental do VelvetVerse Notícias. Testámos a leitura de assuntos internacionais, notícias portuguesas, informação desportiva do Canadá, futebol de Portugal e meteorologia. A versão definitiva utilizará acontecimentos atuais e confirmados, com textos próprios para rádio, e terminará sempre dentro da janela disponível, entre o meio-dia e o meio-dia e meia, hora de Toronto. Obrigado por acompanhar este ensaio. A programação normal do Alma Portuguesa continua na VelvetVerse Radio. Not created to impress. Created to express."]];
OUT=Path("noticias-teste")
OUT.mkdir(exist_ok=True)
PARAS=[p for _,p in SECTIONS]
TEXT="\n\n".join(PARAS)
WORDS=len(TEXT.split())
BYTES=sum(len(p.encode("utf-8")) for p in PARAS)
PRICE_USD_PER_MILLION=15.0
preview={"natureza":"ENSAIO DE LOCUCAO — NAO EMITIR","palavras":WORDS,"bytes_faturaveis_estimados":BYTES,
"segmentos":len(PARAS),"duracao_prevista_min_125ppm":round(WORDS/125,1),
"duracao_prevista_min_145ppm":round(WORDS/145,1),
"custo_fish_s21_pro_usd":round(BYTES/1_000_000*PRICE_USD_PER_MILLION,4),
"custo_fish_s21_pro_free_usd":0.0}
(OUT/"custo-voz.json").write_text(json.dumps(preview,ensure_ascii=False,indent=2),encoding="utf-8")
(OUT/"texto-teste-voz.txt").write_text(TEXT,encoding="utf-8")
print("RESUMO CUSTO TESTE:",json.dumps(preview,ensure_ascii=False),flush=True)
if os.environ.get("VV_ONLY_ESTIMATE","true").lower()=="true":
    print("Simulação apenas: sem API e sem MP3.");raise SystemExit(0)
key=os.getenv("FISH_AUDIO_API_KEY","")
voice=os.getenv("FISH_VOICE_REFERENCE_ID","")
model="s2.1-pro-free"
if not key or not voice:
    raise SystemExit("Chave ou referência da voz por configurar; sem despesas.")
parts=OUT/"partes-voz"
parts.mkdir(exist_ok=True)
audio=[]
for i,paragraph in enumerate(PARAS):
    payload=json.dumps({"text":paragraph,"reference_id":voice,"format":"mp3"},ensure_ascii=False).encode("utf-8")
    req=urllib.request.Request("https://api.fish.audio/v1/tts",payload,method="POST",
       headers={"Authorization":"Bearer "+key,"Content-Type":"application/json","model":model})
    with urllib.request.urlopen(req,timeout=240) as resp:
        buf=resp.read()
    if not (buf.startswith(b"ID3") or (len(buf)>2 and buf[0]==255 and buf[1]&224==224)):
        raise SystemExit("Resposta inesperada: não é MP3 válido")
    path=parts/("secao-%02d.mp3"%i);path.write_bytes(buf);audio.append(path)
    print("Segmento de ensaio",i+1,"de",len(PARAS),"gerado.",flush=True)
listing=parts/"lista.txt"
listing.write_text("\n".join("file '"+f.resolve().as_posix()+"'" for f in audio)+"\n",encoding="utf-8")
output=OUT/"velvetverse-noticias-ensaio-de-custos-NAO-EMITIR.mp3"
subprocess.run(["ffmpeg","-hide_banner","-loglevel","error","-y","-f","concat","-safe","0",
"-i",str(listing),"-af","loudnorm=I=-16:TP=-1.5:LRA=11","-codec:a","libmp3lame","-b:a","192k",str(output)],check=True)
duration=float(subprocess.check_output(["ffprobe","-v","error","-show_entries","format=duration",
"-of","default=noprint_wrappers=1:nokey=1",str(output)]).decode().strip())
if duration>1800 or duration<60:
    output.unlink(missing_ok=True);raise SystemExit("Duração fora de limites, MP3 eliminado.")
preview["duracao_real_minutos"]=round(duration/60,2)
preview["tamanho_mp3_bytes"]=output.stat().st_size
(OUT/"custo-voz.json").write_text(json.dumps(preview,ensure_ascii=False,indent=2),encoding="utf-8")
print("TESTE COMPLETO DE VOZ:",json.dumps(preview,ensure_ascii=False),flush=True)
print("MP3 apenas para ensaio; RadioDJ e Cloudflare R2 não são utilizados.")
